"""Build the single-file Kaggle script from the tested audit/preparation code.

Run locally after changing either source: python dist/build_onset_kaggle.py
Only prepare_onset_kaggle.py is needed on Kaggle. No embedded exec/import of
project modules: the generated file contains ordinary Python definitions.
"""

import ast
from pathlib import Path


HEADER = '''"""GuitarSet audit AND onset data preparation in ONE Kaggle run.

Paste/run this whole script in the existing trainer notebook, on CPU.
Needs the already attached GuitarSet, numpy and soundfile. No previous JSON,
other scripts, downloads, GPU or token configuration are required.

A new directory is created under OUTPUT_ROOT on each run. At the end, share
only the small summary.json whose full path is printed. This prepares sources,
not a trained model: training_ready=false is expected at this stage.

Generated by dist/build_onset_kaggle.py; edit audit_onset_data.py and
prepare_onset_data.py for library changes, then rebuild this file.
"""

INPUT_DIR = "/kaggle/input"
AUDIO_VARIANT = "auto"
OUTPUT_ROOT = "/kaggle/working"

'''

RUNNER = '''
def run_pipeline(root, output_root, variant="auto", groups=SYNTHETIC_GROUPS,
                 validation_player=VALIDATION_PLAYER, test_player=TEST_PLAYER,
                 seed=SEED, sr=SR, masking_pairs=False):
    import tempfile
    if not root.is_dir():
        raise FileNotFoundError(f"GuitarSet input directory is unavailable: {root}")
    output_root.mkdir(parents=True, exist_ok=True)
    run_dir = Path(tempfile.mkdtemp(prefix="onset-prepared-", dir=output_root)).resolve()
    print(f"Output directory: {run_dir}", flush=True)
    print("Stage 1/2: auditing the attached GuitarSet", flush=True)
    audited = audit(root, variant)
    manifest = run_dir / f"onset_manifest_{audited['selected_variant'] or 'auto'}.json"
    write_json(manifest, audited)
    if not audited["ok"]:
        failed = {"ok": False, "stage": "audit", "inventory": audited["inventory"],
                  "error_count": len(audited["errors"]), "errors": audited["errors"][:10],
                  "full_report": str(manifest)}
        write_json(run_dir / "summary.json", failed)
        raise ValueError(f"Audit failed. Small report: {run_dir / 'summary.json'}. "
                         f"First errors: {audited['errors'][:3]}")
    print(f"Audited {len(audited['sources'])} sources. Manifest: {manifest}", flush=True)
    print("Stage 2/2: preparing source splits and synthetic pairs", flush=True)
    result = prepare(manifest, run_dir / "prepared", validation_player, test_player,
                     groups, seed, sr, masking_pairs=masking_pairs)
    result["prepared_directory"] = str(run_dir / "prepared")
    result["summary_path"] = str(run_dir / "summary.json")
    write_json(run_dir / "summary.json", result)
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input-dir", type=Path, default=Path(INPUT_DIR))
    parser.add_argument("--output-root", type=Path, default=Path(OUTPUT_ROOT))
    parser.add_argument("--variant", choices=("auto", "mic", "mix"), default=AUDIO_VARIANT)
    parser.add_argument("--groups", type=int, nargs=3, default=SYNTHETIC_GROUPS)
    parser.add_argument("--validation-player", default=VALIDATION_PLAYER)
    parser.add_argument("--test-player", default=TEST_PLAYER)
    parser.add_argument("--seed", type=int, default=SEED)
    parser.add_argument("--sr", type=int, default=SR)
    args = parser.parse_args(argv)
    try:
        result = run_pipeline(args.input_dir, args.output_root, args.variant, args.groups,
                              args.validation_player, args.test_player, args.seed, args.sr)
    except (ValueError, OSError, KeyError, TypeError, RuntimeError) as error:
        print(json.dumps({"ok": False, "error": str(error)}, indent=2))
        return 1
    print(json.dumps(result, indent=2))
    print(f"Small summary to share: {result['summary_path']}")
    return 0


if __name__ == "__main__":
    status = main([] if "ipykernel" in sys.modules else None)
    if status:
        raise SystemExit(status)
'''


def build(directory):
    chunks = [HEADER]
    for filename in ("audit_onset_data.py", "prepare_onset_data.py"):
        source = (directory / filename).read_text()
        for node in ast.parse(source).body:
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                chunks.append(ast.get_source_segment(source, node))
            elif isinstance(node, ast.FunctionDef):
                if node.name in ("main", "find_manifest"):
                    continue
                if filename == "audit_onset_data.py" and node.name == "sha256":
                    continue  # Use the equivalent preparation helper for both.
                chunks.append(ast.get_source_segment(source, node))
            elif isinstance(node, ast.Assign) and filename == "prepare_onset_data.py":
                if all(isinstance(target, ast.Name) and target.id not in ("MANIFEST", "OUTPUT_DIR")
                       for target in node.targets):
                    chunks.append(ast.get_source_segment(source, node))
    chunks.append(RUNNER)
    return "\n\n".join(chunks).rstrip() + "\n"


if __name__ == "__main__":
    directory = Path(__file__).resolve().parent
    output = directory / "prepare_onset_kaggle.py"
    output.write_text(build(directory))
    print(output)
